package mz.bam.seeky.android;
import android.app.*;import android.content.*;import android.content.pm.*;import android.net.Uri;import android.os.*;import android.speech.tts.TextToSpeech;import java.io.*;import java.nio.file.*;import java.util.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import org.robolectric.shadows.*;import static org.junit.Assert.*;import static org.robolectric.Shadows.shadowOf;

@RunWith(RobolectricTestRunner.class) @Config(manifest=Config.NONE,sdk=33,application=Application.class) @LooperMode(LooperMode.Mode.PAUSED)
public class AndroidIntegration513Test {
 Application app;@Before public void before(){app=RuntimeEnvironment.getApplication();}
 void engine(String id,String label,boolean enabled){ResolveInfo r=new ResolveInfo();r.serviceInfo=new ServiceInfo();r.serviceInfo.packageName=id;r.serviceInfo.name=id+".TtsService";r.serviceInfo.enabled=enabled;r.nonLocalizedLabel=label;r.serviceInfo.applicationInfo=new ApplicationInfo();r.serviceInfo.applicationInfo.packageName=id;r.serviceInfo.applicationInfo.enabled=true;shadowOf(app.getPackageManager()).addResolveInfoForIntent(new Intent(TextToSpeech.Engine.INTENT_ACTION_TTS_SERVICE),r);}
 @Test public void engineDiscoveryFindsNewPackagesAndDeduplicatesTheirServices(){engine(GoogleVoiceSetup.GOOGLE,"Google",true);engine("tts.new.engine","Nova voz",true);engine("tts.new.engine","Serviço repetido",true);engine("tts.disabled","Disabled",false);List<VoiceEngines.Engine> all=VoiceEngines.scan(app);assertEquals(2,all.size());assertEquals(GoogleVoiceSetup.GOOGLE,all.get(0).id);assertEquals("tts.new.engine",all.get(1).id);engine("tts.third.engine","Outra voz",true);assertEquals(3,VoiceEngines.scan(app).size());}
 @Test public void explicitRefreshUpdatesTheEngineScreenWithoutRestartingSeeky(){engine(GoogleVoiceSetup.GOOGLE,"Google",true);org.robolectric.android.controller.ActivityController<VoiceEnginesActivity> c=Robolectric.buildActivity(VoiceEnginesActivity.class).create().start().resume().visible();try{assertFalse(BooksToolsTest.labels(c.get().content).contains("Voz instalada agora"));engine("tts.new.engine","Voz instalada agora",true);c.get().load();assertTrue(BooksToolsTest.labels(c.get().content).contains("Voz instalada agora"));}finally{c.pause().stop().destroy();}}
 @Test public void sendMultipleRetainsEveryUniqueFileAndIncludesClipOnlyFiles(){ArrayList<Uri> uris=new ArrayList<>();for(int i=0;i<1205;i++)uris.add(Uri.parse("content://share/"+i));Intent input=new Intent(Intent.ACTION_SEND_MULTIPLE).setType("*/*").putParcelableArrayListExtra(Intent.EXTRA_STREAM,uris);ClipData clips=ClipData.newRawUri("duplicate",uris.get(0));clips.addItem(new ClipData.Item(Uri.parse("content://share/extra")));input.setClipData(clips);List<Uri> all=IncomingActivity.streams(input);assertEquals(1206,all.size());assertEquals(uris.get(1204),all.get(1204));}
 @Test public void arbitraryFileMimeAndReadGrantReachTheInternalReader()throws Exception{try(WorkTestSupport work=new WorkTestSupport()){Uri uri=work.source("shared","Matéria.txt","Texto recebido.");org.robolectric.android.controller.ActivityController<IncomingActivity> c=Robolectric.buildActivity(IncomingActivity.class,new Intent(Intent.ACTION_SEND).setType("text/plain").putExtra(Intent.EXTRA_STREAM,uri)).create().start().resume();try{c.get().open(uri,"Matéria.txt","text/plain");Intent opened=shadowOf(c.get()).getNextStartedActivity();assertEquals(ReaderActivity.class.getName(),opened.getComponent().getClassName());assertEquals(uri,opened.getData());assertTrue((opened.getFlags()&Intent.FLAG_GRANT_READ_URI_PERMISSION)!=0);assertEquals(uri,opened.getClipData().getItemAt(0).getUri());}finally{c.pause().stop().destroy();}}}
 @Test public void sharingHttpLocationsCannotTurnIntoAutomaticDownloads(){Intent input=new Intent(Intent.ACTION_SEND).putExtra(Intent.EXTRA_STREAM,Uri.parse("https://example.invalid/file.apk"));assertTrue(IncomingActivity.streams(input).isEmpty());assertTrue(IncomingActivity.streams(new Intent(Intent.ACTION_VIEW,Uri.parse("seeky://private"))).isEmpty());}
 @Test public void installerGetsOneReadOnlyApkHandleAndTheAndroidMime()throws Exception{org.robolectric.android.controller.ActivityController<ApkInstallActivity> c=Robolectric.buildActivity(ApkInstallActivity.class,new Intent().setData(Uri.parse("content://share/app.apk"))).create();try{ApkInstallActivity a=c.get();File file=new File(ApkInstallActivity.directory(a),UUID.randomUUID()+".apk");Files.write(file.toPath(),new byte[]{'P','K',3,4});a.prepared=file;Intent install=a.installer();assertEquals(Intent.ACTION_VIEW,install.getAction());assertEquals(ApkInstallActivity.MIME,install.getType());assertEquals("content",install.getData().getScheme());assertTrue((install.getFlags()&Intent.FLAG_GRANT_READ_URI_PERMISSION)!=0);assertEquals(0,install.getFlags()&Intent.FLAG_GRANT_WRITE_URI_PERMISSION);assertEquals(install.getData(),install.getClipData().getItemAt(0).getUri());ProviderInfo p=new ProviderInfo();p.authority=a.getPackageName()+".files";FileShareProvider provider=new FileShareProvider();provider.attachInfo(a,p);try(ParcelFileDescriptor fd=provider.openFile(install.getData(),"r")){assertEquals(4,fd.getStatSize());}try{provider.openFile(install.getData(),"w");fail();}catch(FileNotFoundException expected){}try{provider.openFile(new Uri.Builder().scheme("content").authority(p.authority).appendPath("apk").appendPath("../secret.apk").build(),"r");fail();}catch(FileNotFoundException expected){}}finally{c.destroy();}}
}
